import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"开发手册","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/dev-guide/index.md","filePath":"zh-CN/dev-guide/index.md","lastUpdated":1785993908000}'),s={name:"zh-CN/dev-guide/index.md"};function i(n,e,l,d,c,g){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="开发手册" tabindex="-1">开发手册 <a class="header-anchor" href="#开发手册" aria-label="Permalink to &quot;开发手册&quot;">​</a></h1><p>Lertaro 提供了一套开放的插件 SDK(<code>Lertaro.PluginSdk</code>)，第三方程序集可以引用它来扩展搜索行为、添加右键菜单动作、与其他窗口集成，以及自定义界面。本手册记录了这套 SDK 的全部内容。</p><ul><li><strong><a href="./architecture.html">架构设计</a></strong> —— App、后台 Service 与插件之间是如何配合的。</li><li><strong><a href="./getting-started.html">快速上手</a></strong> —— 搭建一个插件项目并加载它。</li><li><strong>插件 SDK 参考</strong>: <ul><li><strong><a href="./sdk/core-search-actions.html">核心检索与动作</a></strong> —— 贡献搜索结果与结果动作。</li><li><strong><a href="./sdk/system-adapters.html">系统与对话框适配</a></strong> —— 与文件资源管理器、原生文件对话框及其他前台窗口集成。</li><li><strong><a href="./sdk/ui-extensions.html">界面与预览扩展</a></strong> —— 侧栏过滤器、结果列、文件预览、缩略图、主题与语言包。</li><li><strong><a href="./sdk/abstractions.html">共享抽象契约</a></strong> —— 插件收到的只读模型(<code>ISearchResult</code>、 <code>IPluginSearchWindow</code>)以及配置模式(<code>IConfigurable</code>)。</li><li><strong><a href="./sdk/services.html">宿主服务</a></strong> —— 宿主暴露给插件的静态服务(图标、收藏夹、历史记录、文件元数据、目录索引、插件专属设置、日志)。</li></ul></li><li><strong><a href="./examples.html">插件示例</a></strong> —— 两个真实随附插件的案例分析。</li><li><strong><a href="./packaging.html">打包与发布</a></strong> —— 编译好的插件 DLL 是如何被发现并加载的。</li></ul><p>本手册里的每一个接口签名都直接对照当前 <code>PluginSdk</code> 源码核实过——如果发现和文档有出入，以代码为准。</p>',4)])])}const p=t(s,[["render",i]]);export{m as __pageData,p as default};
